templates.body:
GOOSE_DISABLE_KEYRING: true
GOOSE_TELEMETRY_ENABLED: false
active_provider: openai
providers:
  openai:
    enabled: true
    configured: true
    model: {{model_alias}}
GOOSE_PROVIDER: openai
GOOSE_MODEL: {{model_alias}}
GOOSE_PLANNER_PROVIDER: openai
GOOSE_PLANNER_MODEL: {{model_slot_plan}}
OPENAI_HOST: {{base_url}}
OPENAI_BASE_PATH: chat/completions
{{#if mcp_servers}}extensions:
{{#each mcp_servers}}  {{quoted slug}}:
    enabled: true
{{#if local}}    type: stdio
    name: {{quoted slug}}
    cmd: {{quoted command}}
{{#if args}}    args:
{{#each args}}      - {{quoted value}}
{{/each}}{{/if}}{{#if env}}    envs:
{{#each env}}      {{name}}: {{quoted value}}
{{/each}}{{/if}}    timeout: 300
{{else}}    type: streamable_http
    name: {{quoted slug}}
    uri: {{quoted url}}
    timeout: 300
{{#if headers}}    headers:
{{#each headers}}      {{name}}: {{quoted value}}
{{/each}}{{/if}}{{/if}}{{/each}}{{/if}}
